import { describe, expect, it } from "vitest";
import { z } from "zod";
import examplesJson from "../../examples/plugin-examples.json";
import overviewJson from "../../examples/plugins-overview.json";
import { createPreviewTransport } from "./preview";
import { exampleInfoSchema, pluginManifestSchema, pluginsOverviewSchema, scanReportSchema } from "./schema";

// Generated by the Rust host (`cargo run --example dump_plugins`) and guarded
// against drift by a Rust test, so this is the real IPC contract for the
// Plugins screen.
const fixture: unknown = overviewJson;

describe("plugins contract with Rust", () => {
  const overview = pluginsOverviewSchema.parse(fixture);
  const byId = (id: string) => overview.plugins.find((p) => p.plugin.id === id)!;

  it("parses what the host emits for installed plugins, failed ones and rejected folders", () => {
    expect(overview.plugins.map((p) => p.plugin.id).sort()).toEqual([
      "example.broken",
      "example.counter",
      "example.hello",
      "example.home-assistant",
      "example.home-assistant-unset",
    ]);
    expect(overview.issues).toHaveLength(1);
    expect(overview.folders.length).toBeGreaterThan(0);
  });

  it("tells a healthy plugin from a failed one by status, with the reason in plain words", () => {
    expect(byId("example.counter").plugin.external?.status).toBe("enabled");
    const broken = byId("example.broken").plugin.external;
    expect(broken?.status).toBe("error");
    expect(broken?.error).toMatch(/does not provide/);
  });

  it("describes typed actions and the events a plugin may publish", () => {
    const hello = byId("example.hello").plugin;
    expect(hello.kind).toBe("plugin");
    expect(hello.actions[0]?.params).toMatchObject([{ name: "name", type: "string", required: false, maxLength: 60 }]);
    expect(hello.actions[0]).toMatchObject({ category: "Greetings", appearance: { label: "Hello" } });
    expect(hello.actions[0]?.keywords).toContain("greet");
    expect(hello.external?.events.map((e) => e.type)).toEqual(["hello.completed"]);
    // Actions without settings still carry an empty list, so the UI never branches on undefined.
    expect(byId("example.counter").plugin.actions.every((a) => Array.isArray(a.params))).toBe(true);
  });

  it("never carries the value of a secret setting", () => {
    const token = byId("example.hello").config.find((c) => c.key === "token")!;
    expect(token.secret).toBe(true);
    expect(token.isSet).toBe(true);
    expect(token).not.toHaveProperty("value");
    expect(JSON.stringify(fixture)).not.toContain("super-secret-value");
  });

  it("says which plain-text secret needs migrating, by name, on the plugin itself", () => {
    expect(byId("example.hello").secretMigration).toEqual({ migrationRequired: ["token"], needsUpdate: [] });
    for (const p of overview.plugins.filter((x) => x.plugin.id !== "example.hello")) expect(p.secretMigration).toBeUndefined();
  });

  it("shows plain settings with their value and default", () => {
    const greeting = byId("example.hello").config.find((c) => c.key === "greeting")!;
    expect(greeting.value).toBe("Hola");
    expect(greeting.default).toBe("Hello");
    expect(byId("example.counter").config.find((c) => c.key === "step")?.default).toBe(1);
  });

  it("still accepts built-in plugins, which have no external block", () => {
    const builtIn = pluginManifestSchema.parse({
      id: "keyboard",
      name: "Keyboard",
      version: "1.0.0",
      description: "Presses a key combination.",
      actions: [{ id: "press", label: "Press", description: "Press keys." }],
      states: [],
      permissions: ["automation"],
    });
    expect(builtIn.external).toBeUndefined();
    expect(builtIn.actions[0]?.params).toEqual([]);
    expect(builtIn.kind).toBe("builtin");
  });

  it("says what a plugin asks of the network and what was decided, per exact destination", () => {
    const net = byId("example.home-assistant").network!;
    expect(net.purpose).toBe("Connect to your Home Assistant instance.");
    expect(net.status).toBe("granted");
    expect(net.hosts).toMatchObject([{ origin: "http://192.168.1.20:8123", reach: "local", status: "granted", source: { kind: "setting", key: "baseUrl" } }]);
    expect(net.hosts[0]!.decidedAt).toBeGreaterThan(0);
    // The decision about the address it had before is still on file, and marked as covering nothing.
    expect(net.stale).toEqual([{ origin: "http://homeassistant.local:8123", decision: "denied" }]);
    expect(byId("example.home-assistant").plugin.permissions).toEqual(["network"]);
    // A plugin that asks for nothing has no network block at all.
    expect(byId("example.counter").network).toBeUndefined();
    expect(byId("example.counter").plugin.permissions).toEqual([]);
  });

  it("says why a setting gives no destination yet, and why the last request failed", () => {
    const unset = byId("example.home-assistant-unset");
    expect(unset.network).toMatchObject({ status: "needsApproval", hosts: [], unresolved: [{ setting: "baseUrl" }] });
    expect(unset.network!.unresolved[0]!.reason).toMatch(/not a URL/);
    expect(unset.networkFailure).toMatchObject({ code: "invalid_request" });
    expect(unset.networkFailure!.at).toBeGreaterThan(0);
    expect(unset.secrets[0]).toMatchObject({ key: "token", isSet: false });
    expect(unset.secrets[0]).not.toHaveProperty("origin");
  });

  it("carries a secret's name, where it goes and whether it is set, never its value", () => {
    const ha = byId("example.home-assistant");
    expect(ha.secrets).toEqual([
      {
        key: "token",
        label: "Long-lived access token",
        description: expect.stringContaining("Long-lived access tokens"),
        isSet: true,
        origin: "http://192.168.1.20:8123",
      },
    ]);
    expect(ha.secretStore).toBe("memory");
    // Where secrets are kept is said once for the whole screen, with whether it can be used.
    expect(pluginsOverviewSchema.parse(fixture).secretStore).toEqual({ kind: "memory", available: true, name: "memory" });
    // What an earlier version left in a plain file, or in a plugin's settings, is listed by name only.
    expect(pluginsOverviewSchema.parse(fixture).legacySecrets).toEqual({
      entries: [
        { plugin: "example.home-assistant-unset", pluginName: "Home Assistant (not set up)", key: "token", source: "file" },
        { plugin: "example.hello", pluginName: "Hello Plugin", key: "token", source: "settings" },
      ],
      file: "<data>/secrets.json",
      unreadable: false,
    });
    expect(JSON.stringify(fixture)).not.toContain("a-token-from-the-plain-file-era");
    expect(ha.refreshSeconds).toBe(5);
    expect(JSON.stringify(fixture)).not.toContain("a-long-lived-access-token");
    // The address is a setting, shown with the name its manifest gives it.
    expect(ha.config).toMatchObject([{ key: "baseUrl", label: "Home Assistant address", value: "http://192.168.1.20:8123", secret: false }]);
    // Older manifests give no label: the key stands in.
    expect(byId("example.hello").config.find((c) => c.key === "greeting")!.label).toBe("greeting");
  });

  it("parses the scan summary", () => {
    expect(scanReportSchema.parse({ loaded: 1, reloaded: 0, unchanged: 2, removed: 0, issues: 1 }).issues).toBe(1);
  });

  // `examples/plugin-examples.json`: what `plugins_examples` answers for the
  // three examples the app ships, Counter installed (`cargo run --example
  // dump_plugin_examples`, guarded by tests/plugins_contract.rs).
  it("parses the example plugins as Rust describes them", () => {
    const examples = z.array(exampleInfoSchema).parse(examplesJson);
    expect(examples).toEqual(examplesJson);
    expect(examples.map((e) => [e.id, e.installed, e.network])).toEqual([
      ["example.counter", true, false],
      ["example.hello", false, false],
      ["example.home-assistant", false, true],
    ]);
    expect(exampleInfoSchema.safeParse({ ...examples[0], installed: undefined }).success).toBe(false);
  });
});

describe("preview transport and plugins", () => {
  it("shows an empty plugin list and refuses to manage plugins without the desktop runtime", async () => {
    const t = await createPreviewTransport();
    expect(pluginsOverviewSchema.parse(await t.invoke("plugins_list"))).toEqual({
      plugins: [],
      issues: [],
      folders: [],
      secretStore: { kind: "memory", available: true, name: "memory" },
      legacySecrets: { entries: [], unreadable: false },
    });
    await expect(t.invoke("plugins_rescan")).rejects.toMatch(/desktop app/);
    // No example plugin is offered, and none can be installed or shown on disk.
    expect(await t.invoke("plugins_examples")).toEqual([]);
    await expect(t.invoke("plugins_install_example", { id: "example.hello" })).rejects.toMatch(/desktop app/);
    await expect(t.invoke("plugins_reveal_folder")).rejects.toMatch(/desktop app/);
    for (const command of ["plugins_set_permission", "plugins_set_secret", "plugins_clear_secret", "plugins_migrate_legacy_secrets", "plugins_discard_legacy_secrets", "plugins_migrate_plugin_legacy_secrets", "plugins_remove_plugin_legacy_secrets"]) {
      await expect(t.invoke(command, { id: "x" })).rejects.toMatch(/desktop app/);
    }
  });
});
